insert into public.university_sources (university_id, source_url, source_domain, source_type, confidence, raw_excerpt)
select u.id, u.website_url, regexp_replace(u.website_url, '^https?://(www\.)?', ''), 'official_institution_website', u.data_confidence::text::data_confidence,
  'Institution identity taken from the official institution website, cross-checked 2026-08-15 against the founder''s school-counselor Drive corpus. No admissions statistics asserted.'
from public.universities u
where (lower(u.name), u.country) in (('école polytechnique', 'France'), ('escp business school', 'France'), ('essec business school', 'France'), ('université paris dauphine - psl', 'France'), ('constructor university', 'Germany'), ('frankfurt school of finance and management', 'Germany'), ('humboldt university of berlin', 'Germany'), ('lmu munich', 'Germany'), ('technical university of munich', 'Germany'), ('university of mannheim', 'Germany'), ('luiss guido carli', 'Italy'), ('politecnico di milano', 'Italy'), ('sapienza university of rome', 'Italy'), ('university of bologna', 'Italy'), ('eindhoven university of technology', 'Netherlands'), ('tilburg university', 'Netherlands'), ('university of groningen', 'Netherlands'), ('epfl', 'Switzerland'), ('university of st. gallen', 'Switzerland'), ('university of zurich', 'Switzerland'), ('özyeğin university', 'Turkey'), ('king''s college london', 'United Kingdom'), ('university of edinburgh', 'United Kingdom'), ('university of warwick', 'United Kingdom'), ('columbia university', 'United States'), ('new york university', 'United States'), ('princeton university', 'United States'), ('university of california, berkeley', 'United States'), ('university of chicago', 'United States'), ('university of pennsylvania', 'United States'), ('yale university', 'United States'))
  and not exists (select 1 from public.university_sources s where s.university_id = u.id)
on conflict do nothing;

