-- ===== University requirements: 520 rows, pivoted from the corpus's one-row-per-programme
-- shape into ORYN's one-row-per-requirement-type shape. structured_rule is deliberately left NULL —
-- per migration 0020's own rule, it's only ever populated from admin-reviewed AI structuring, never
-- an unreviewed import; every row here evaluates as needs_manual_review until an admin structures it,
-- which is the correct, honest default. =====
insert into public.university_requirements (university_id, program_id, requirement_type, title, requirement_detail, source_url, data_confidence, data_status, retrieved_at, last_checked_at)
select u.id, p.id, v.requirement_type::requirement_category, v.title, v.requirement_detail, v.source_url, 'medium'::data_confidence, 'fresh'::data_status, timestamptz '2026-08-15', timestamptz '2026-08-15'
