on conflict (program_id, requirement_type) do nothing;

-- ===== Opportunities: 273 verified-identity records (125 active, 147 under_review, 1 expired). =====
-- source_confidence: 'high' where the official/provider page itself was directly and cleanly
-- retrieved; 'medium' where identity was corroborated by an official-domain search result instead.
-- status: 'active' = 2026-cycle evidence found and not flagged closed; 'under_review' = identity
-- verified but no current-cycle date evidence (never presented with a specific deadline); 'expired'
-- = 2026-cycle evidence found but explicitly flagged closed/passed. Never fabricates a date.
